  /**
   * <!-- begin-user-doc -->
   * <!-- end-user-doc -->
   * <!-- begin-model-doc -->
   * Summary: Fills pipes within the specified distance from source using BFS-style expansion.
   * Water propagates along pipes only when adjacent pipes have matching connection directions
   * (one pipe's direction must be the opposite of the other).
   * Algorithm:
   *   if distance == 0: return
   *   queue = new Queue<Coordinate>()
   *   visited = new Set<Coordinate>()
   *   queue.enqueue(sourceCell.coord)
   *   visited.add(sourceCell.coord)
   *   currentDistance = 0
   *   while queue is not empty and currentDistance < distance:
   *     levelSize = queue.size()
   *     for i = 0 to levelSize - 1:
   *       current = queue.dequeue()
   *       cell = cells[current.row][current.col]
   *       if cell is FillableCell and cell.pipe is not null and not cell.pipe.filled:
   *         cell.pipe.filled = true
   *         filledTiles.add(current)
   *         prevFilledTiles++
   *       if cell is FillableCell or cell is TerminationCell:
   *         directions = (cell is FillableCell) ? cell.pipe.getConnections() : [cell.pointingTo]
   *         for each direction in directions:
   *           neighbor = current.add(Pa19Helper.getOffset(direction))
   *           if neighbor not in visited and within bounds:
   *             neighborCell = cells[neighbor.row][neighbor.col]
   *             if neighborCell is FillableCell with pipe and neighborCell.pipe.getConnections() contains Pa19Helper.getOpposite(direction):
   *               queue.enqueue(neighbor)
   *               visited.add(neighbor)
   *     currentDistance++
   * Related Features: cells field, filledTiles field, prevFilledTiles field, sourceCell field
   * Related Classes: Coordinate, Direction, Pa19Helper, FillableCell, Pipe, TerminationCell
   * Input: distance: int - the number of steps to fill from source
   * Output: None
   * Pre-condition: distance >= 0
   * Post-condition: Pipes within the specified distance from source are marked as filled
   * <!-- end-model-doc -->
   * @model annotation="http://www.ustb.edu.cn/sei/mde/EnhancedCodeGen generated='true'"
   * @generated NOT
   */
  public void fillTiles(final int distance)
  {
    if (distance == 0) {
      return;
    }
    Queue<Coordinate> queue = new LinkedList<Coordinate>();
    Set<Coordinate> visited = new HashSet<Coordinate>();
    Pa19Helper helper = Pa19Factory.eINSTANCE.createPa19Helper();
    queue.add(sourceCell.getCoord());
    visited.add(sourceCell.getCoord());
    int currentDistance = 0;
    while (!queue.isEmpty() && currentDistance <= distance) {
      int levelSize = queue.size();
      for (int i = 0; i < levelSize; i++) {
        Coordinate current = queue.poll();
        Cell cell = this.cell[current.getRow()][current.getCol()];
        if (cell instanceof FillableCell) {
          FillableCell fillableCell = (FillableCell) cell;
          Pipe pipe = fillableCell.getPipe();
          if (pipe != null && !pipe.isFilled()) {
            pipe.setFilled(true);
            getFilledTiles().add(current);
            prevFilledTiles++;
          }
        }
        if (cell instanceof FillableCell || cell instanceof TerminationCell) {
          EList<Direction> directions;
          if (cell instanceof FillableCell) {
            Pipe pipe = ((FillableCell) cell).getPipe();
            if (pipe == null) {
              continue;
            }
            directions = pipe.getConnections();
          } else {
            directions = new BasicEList<Direction>();
            directions.add(((TerminationCell) cell).getPointingTo());
          }
          for (Direction direction : directions) {
            Coordinate neighbor = current.add(helper.getOffset(direction));
            if (!visited.contains(neighbor) &&
                neighbor.getRow() >= 0 && neighbor.getRow() < rows &&
                neighbor.getCol() >= 0 && neighbor.getCol() < cols) {
              Cell neighborCell = this.cell[neighbor.getRow()][neighbor.getCol()];
              if (neighborCell instanceof FillableCell) {
                Pipe neighborPipe = ((FillableCell) neighborCell).getPipe();
                if (neighborPipe != null &&
                    neighborPipe.getConnections().contains(helper.getOpposite(direction))) {
                  queue.add(neighbor);
                  visited.add(neighbor);
                }
              }
            }
          }
        }
      }
      currentDistance++;
    }
  }

